      pushed.stdout.includes("cachet: uploaded 2 objects"),
      pushed.stdout,
    );
    const hash = bigPath.match(/\/nix\/store\/([a-z0-9]+)-/)[1];
    const narinfo = await fetch(`${base}/${hash}.narinfo`, {
      headers: READ_AUTH(),
    });
    assert.equal(
      narinfo.status,
      200,
      "the multipart nar verified and signed",
    );

