  name: {
    fontFamily: font.ui,
    fontSize: text.spec,
    lineHeight: leading.spec,
    color: color.text,
    overflow: "hidden",
    textOverflow: "ellipsis",
    whiteSpace: "nowrap",
  },
  track: { height: "8px", backgroundColor: color.ink3, position: "relative" },
  fill: {
    height: "100%",
    backgroundColor: color.text,
    transitionProperty: "width",
    transitionDuration: "420ms",
    transitionTimingFunction: "cubic-bezier(0.2, 0.8, 0.2, 1)",
  },
  fillSignal: { backgroundColor: color.signal },
  figure: {
    fontFamily: font.ui,
    fontSize: text.spec,
    lineHeight: leading.spec,
    fontWeight: weight.bold,
    color: color.text,
    textAlign: "right",
